void *DrawCarStatBars(void *x, int a1)
{
  int s3 = 0x78;
  int i = 0;
  int s0;
  int s2;
  int a;
  do
  {
    s2 = a1 - (i * 0x32);
    if (s2 >= 0x81)
    {
      s2 = 0x80;
    }
    else
      if (s2 < 0)
    {
      s2 = 0;
    }
    s0 = SelectionState.fields.phase17 >> 1;
    if (s0 >= 3)
    {
      s0 = 2;
    }
    if (i == 2)
    {
      s0 += 0xB;
      a = s0;
    }
    else
    {
      a = s0;
      if (i == 1)
      {
        s0 = SelectionState.fields.phase17 + 3;
        a = s0;
      }
    }
    s3 += CourseSelectGroupCounts[i];
    x = AddBadgeSpriteStrip(a, &CurrentDrawBuf->buffer.ordering70.tags[0], x, 0x20, s3, s2);
    if (i == 1)
    {
      const UiUvRect *t;
      int b = BadgeStripPatterns[s0 * 8 + 4];
      s0 = GpStageCourseBaseIndex[SelectionState.fields.phase17] + 0x20;
      t = &BadgeGlyphUvTable[s0];
      x = AddSpriteWithDrawMode(&CurrentDrawBuf->buffer.ordering70.tags[0], x, b + 0x34, s3, t->w, t->h, t->u, t->v, 0x4A, 0x2E28, i, s2);
    }
    i++;
  }
  while (i < 3);
  return x;
}

void *DrawStepProgressBar(GpuDmaTag *a0, void *a1) {
    int s0 = 0x28;
    int sel = SelectionState.fields.phase17;
    int i = 0;
    int v, y;
    do {
        s0 += MakerTeamCarCounts[i];
        if (sel == i) {
            v = rsin((ModeFrame << 6) & 0xFC0) / 64 + 0xBF;
        } else if (i < sel) {
            v = 0x80;
        } else {
            s0 += 8;
            goto next;
        }
        y = s0;
        s0 += 8;
        a1 = AddTilePrim(&CurrentDrawBuf->buffer.ordering70.tags[0], a1, y, 0x190, 8, 0x1C, v, v, v);
next:
        i++;
    } while (i < 8);
    return a1;
}

void DialogueIntroModeUpdate(void)
{
    int t;
    if (ModeFrame <= 0x7FFFU) {
        ModeFrame += 1;
    }
    UpdateScreenFade(0x1000B);
    if (BadgeRows->state10 >= 4) {
        UpdateBadgeRowAnim(0);
    }
    if ((u8)UiRows->byte14 >= 3) {
        DrawUiRow(0);
    }
    if (ImageRows->f1 >= 3) {
        UpdateImageRow(0);
    }
    if (ModeFrame >= 3U) {
        DialogueSceneMode = 1;
        t = LoadDialogueStep();
        if (t == 1) {
            if (StepMenuCameraTransition(MENU_TRANSITION_ALL) == MENU_TRANSITION_ALL) {
                ModeFrame = 0;
                InitBadgeRow(0, 0xC, 0x130, 0x128, RR_PAL_JP(0x6C, 0x58), 0, 0);
                InitRect16Row(0, 0x10, 0x48, 0x120, 0x120, 0, 0);
                InitImageRow(0, -1, 0, 0);
                ModeGroup = t;
                ModeIndex = 0xC;
                SubmodeState = 0;
            }
        }
    } else {
        SetMenuFrameOptions(0, 1, 0);
    }
}

void DialogueSceneSetup(void) {
    SetupDrawDispEnvs(0, 0, 0, 2);
    ModeFrame = 0;
    VSyncThreshold = 0x80;
    ActiveSceneId = 0x10C;
}

void DialogueModeUpdate(void) {
    int s0;
    BadgeRow1C *tab;
    int a1;
    ModeFrame += 1;
    ScreenFrame += 1;
    if (UpdateImageRow(0) > 0) {
        UpdateDialoguePanel();
    }
    UpdateDialogueBox();
    /* The PAL release also lets Start skip the dialogue. */
    if (Dialogue->st == 4 || (!RR_RELEASE_JP && (Pad0Buttons & 0x800))) {
        s0 = BadgeRows[Dialogue->s16].state10;
        if (s0 == 3) {
            if (RR_RELEASE_JP ? MenuReturnSubmodeIndex != 0
                              : (PlayerControllers[0].action28 != 0 || (PlayerControllers[0].edges08.fields.pressed & 0x800))) {
                PlaySfx(1);
                SetMenuFrameOptions(0, 1, 0);
                tab = BadgeRows;
                tab[Dialogue->s16].state10 = 4;
                ImageRows->f1 = s0;
                FadeCountdown = 0;
                if (PendingModeId == 0x10F || PendingModeId == 0x12A || PendingModeId == 0x205) {
                    FadeCountdown = 0x40;
                    ResetScreenCounters();
                    LoadCursor = MenuArenas.second;
                    LoadTimListStep(0);
                    SeqFadeVolume(0, (short)(FadeCountdown - 4));
                    SubmodeState = 1;
                } else if (PendingModeId == 0x111) {
                    FadeCountdown = 0x40;
                    SeqFadeVolume(0, 0x3C);
                    SubmodeState = 1;
                }
            }
        }
    }
    if (SubmodeState == 1) {
        if ((short)FadeCountdown > 0) {
            FadeCountdown -= 1;
        }
        AddScreenFadeTiles(&CurrentDrawBuf->buffer.ordering70.tags[0], (0x40 - (short)FadeCountdown) * 4, 0x45);
    }
    if (BadgeRows[Dialogue->s16].state10 == 0xB) {
        if (ImageRows->f1 == 5) {
            if (PendingModeId == 0x10F || PendingModeId == 0x12A) {
                if (LoadTimListStep(1) == 1) {
                    SeqMuteVolume();
                    if ((short)FadeCountdown <= 0) {
                        unsigned c = PendingModeId;
                        SubmodeState = 0;
                        ModeGroup = c >> 8;
                        ModeIndex = c & 0xFF;
                    }
                }
            } else if (PendingModeId == 0x205) {
                SeqMuteVolume();
                if ((short)FadeCountdown <= 0) {
                    unsigned c = PendingModeId;
                    SubmodeState = 0;
                    ModeGroup = c >> 8;
                    ModeIndex = c & 0xFF;
                }
            } else {
                if ((short)FadeCountdown <= 0) {
                    unsigned c = PendingModeId;
                    SubmodeState = 0;
                    ModeGroup = c >> 8;
                    ModeIndex = c & 0xFF;
                }
            }
        }
    }
    UpdateScreenFade(0x1000A);
}

void AddScreenBackdropTile(void) {
    GpuScratchPointers *g = RR_GPU_SCRATCH;
    g->cursor = AddTilePrim(&CurrentDrawBuf->buffer.ordering70.tags[703], g->cursor, 0, 0, 0x140, RR_PAL_JP(0x200, 0x1E0), 0x20, 0x20, 0x20);
}

